/*
 * A356555  Irregular triangle T(n, k), n > 0, k = 1..A080221(n) read by rows;
 *          the n-th row contains, in ascending order, the bases b from 2..n+1
 *          where the sum of digits of n divides n.
 * https://oeis.org/A356555
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, tabf
 * Formula:   not stated
 * Range:     u8 n <= 79, u16 n <= 79, u32 n <= 79, u64 n <= 79, u128 n <= 79,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generated by iterating the irregular triangle T(n,k).
   For each n ≥ 1, all bases b in [2,n+1] such that
   sum of digits of n in base b divides n are listed.
   The sequence a(n) is the concatenation of these rows. */
#include <stddef.h>

seq_t a(idx_t n) {
    if (n < 1) return 0;            /* undefined for n < 1, but safeguard */
    idx_t remain = n;                /* number of elements still needed */
    for (idx_t r = 1; ; ++r) {       /* iterate rows n = 1, 2, 3, ... */
        seq_t r_val = (seq_t)r;
        for (idx_t b = 2; b <= r + 1; ++b) { /* bases 2 .. n+1 */
            seq_t sum = 0;
            seq_t tmp = r_val;
            seq_t base = (seq_t)b;
            while (tmp) {            /* compute digit sum of n in base b */
                sum += tmp % base;
                tmp /= base;
            }
            if (r_val % sum == 0) {  /* good base */
                --remain;
                if (remain == 0)     /* found the required element */
                    return (seq_t)b;
            }
        }
    }
}
